<?php
declare(strict_types=1);require '../config/db.php';require '../config/auth.php';require_role('parishioner','login.php');$u=current_user();$uid=(int)$u['id'];
$counts=[];foreach(['upcoming'=>"SELECT COUNT(*) FROM appointments WHERE user_id=? AND appointment_date>=CURDATE() AND status IN ('pending','approved')",'pending'=>"SELECT COUNT(*) FROM appointments WHERE user_id=? AND status='pending'",'completed'=>"SELECT COUNT(*) FROM appointments WHERE user_id=? AND status='completed'",'notifications'=>"SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0"] as $k=>$q){$s=$pdo->prepare($q);$s->execute([$uid]);$counts[$k]=(int)$s->fetchColumn();}
$s=$pdo->prepare("SELECT a.*,s.name service_name,r.name resource_name FROM appointments a JOIN services s ON s.id=a.service_id LEFT JOIN resources r ON r.id=a.resource_id WHERE a.user_id=? AND a.appointment_date>=CURDATE() AND a.status IN ('pending','approved') ORDER BY a.appointment_date,a.start_time LIMIT 5");$s->execute([$uid]);$upcoming=$s->fetchAll();$ann=$pdo->query("SELECT * FROM announcements ORDER BY published_at DESC LIMIT 3")->fetchAll();$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$uid]);$pageTitle='Welcome, '.explode(' ',$u['full_name'])[0].'.';$eyebrow='Parishioner Dashboard';
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><?php include 'includes/header.php'?><section class="grid stats parish-dashboard-stats"><div class="card stat"><span class="muted">Upcoming</span><strong><?=$counts['upcoming']?></strong></div><div class="card stat"><span class="muted">Pending</span><strong><?=$counts['pending']?></strong></div><div class="card stat"><span class="muted">Completed</span><strong><?=$counts['completed']?></strong></div><div class="card stat"><span class="muted">New notifications</span><strong><?=$counts['notifications']?></strong></div></section><br><section class="grid two"><div class="card dashboard-upcoming"><div class="topbar dashboard-section-head" style="margin-bottom:15px"><h2>Upcoming appointments</h2><a class="btn small" href="book-service.php">Book service</a></div><?php if(!$upcoming):?><p class="muted">No upcoming appointments yet.</p><?php else:?><div class="table-wrap dashboard-upcoming-wrap"><table class="table dashboard-upcoming-table"><thead><tr><th>Service</th><th>Date</th><th>Time</th><th>Status</th></tr></thead><tbody><?php foreach($upcoming as $a):?><tr><td class="dash-appt-main"><a href="appointment-details.php?id=<?=$a['id']?>"><b><?=e($a['service_name'])?></b></a><br><small><?=e($a['reference_no'])?></small></td><td class="dash-appt-date" data-label="Date"><?=date('M j, Y',strtotime($a['appointment_date']))?></td><td class="dash-appt-time" data-label="Time"><?=date('g:i A',strtotime($a['start_time']))?></td><td class="dash-appt-status"><span class="badge <?=e($a['status'])?>"><?=e($a['status'])?></span></td></tr><?php endforeach?></tbody></table></div><?php endif?></div><div class="card"><h2>Latest announcements</h2><?php if(!$ann):?><p class="muted">No announcements.</p><?php endif?><?php foreach($ann as $a):?><article style="padding:12px 0;border-bottom:1px solid var(--line)"><b><?=e($a['title'])?></b><div class="muted" style="font-size:12px"><?=date('M j, Y',strtotime($a['published_at']))?></div><p><?=e(mb_strimwidth($a['content'],0,140,'…'))?></p></article><?php endforeach?><a class="btn light small" style="margin-top:14px" href="announcements.php">View all</a></div></section></main></div><script src="../assets/js/script.js"></script></body></html>
